descriptor.templateCss:
.dg-card {
    font-family: Roboto, system-ui, -apple-system, Segoe UI, Arial, sans-serif;
    border: 1px solid #dde6ef;
    border-radius: 14px;
    background: #fff;
    height: 100%;
    display: flex;
    flex-direction: column;
    min-height: 0;
    overflow: hidden;
    box-shadow: 0 1px 3px rgba(12, 31, 53, .06)
}

.dg-head {
    padding: 14px 16px;
    border-bottom: 1px solid #e6edf4
}

.dg-title {
    font-size: 12px;
    font-weight: 800;
    letter-spacing: .12em;
    text-transform: uppercase;
    color: #22384f
}

.dg-grid {
    padding: 10px 10px;
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    grid-auto-rows: minmax(126px, auto);
    gap: 8px;
    overflow: auto;
    align-content: start
}

.dg-card-item {
    border: 1px solid #ebf1f7;
    border-radius: 10px;
    background: #ffffff;
    padding: 7px 8px;
    display: flex;
    flex-direction: column;
    min-height: 0;
    position: relative
}

.dg-card-item.good {
    box-shadow: inset 0 3px 0 #32a852
}

.dg-card-item.warn {
    box-shadow: inset 0 3px 0 #efb125
}

.dg-card-item.bad {
    box-shadow: inset 0 3px 0 #e04848
}

.dg-card-item.value {
    justify-content: center
}

.dg-name {
    font-size: 10px;
    color: #2b3f53;
    font-weight: 700;
    line-height: 1.2;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px
}

.dg-expand {
    display: none
}

.dg-gauge-wrap {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    flex: 1 1 auto;
    padding: 4px 0
}

.dg-gauge {
    width: 100%;
    max-width: 160px;
    height: 86px;
    display: block
}

.dg-value-main {
    font-size: 13px;
    font-weight: 800;
    color: #22384f;
    text-align: center;
    margin-top: -2px
}

.dg-value-sub {
    font-size: 9px;
    color: #7c92a8;
    text-align: center;
    margin-top: 2px
}

.dg-ind-label {
    font-size: 11px;
    color: #7c92a8;
    font-weight: 700;
    letter-spacing: .08em;
    text-transform: uppercase
}

.dg-ind-value {
    font-size: 22px;
    line-height: 1;
    font-weight: 800;
    color: #c62828;
    margin-top: 8px
}

.dg-ind-value.green {
    color: #2eaf62
}

.dg-ind-range {
    margin-top: 6px;
    display: flex;
    justify-content: space-between;
    font-size: 12px;
    color: #7c92a8
}

.dg-ind-bar {
    height: 6px;
    border-radius: 999px;
    background: #dfe7ef;
    margin-top: 8px;
    overflow: hidden
}

.dg-ind-fill {
    height: 100%;
    background: #43a047
}

.dg-empty {
    padding: 24px;
    text-align: center;
    color: #7c92a8;
    font-size: 13px
}

.dg-footnote {
    grid-column: 1/-1;
    font-size: 11px;
    color: #7c92a8;
    padding-top: 2px
}

@media(max-width:1600px) {
    .dg-grid {
        grid-template-columns: repeat(3, minmax(0, 1fr))
    }
}

@media(max-width:980px) {
    .dg-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr))
    }
}

@media(max-width:620px) {
    .dg-grid {
        grid-template-columns: 1fr
    }
}

.sg-wrap {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    height: 100%;
    padding: 16px;
    gap: 16px;
    grid-column: 1/-1
}

.sg-scene {
    width: 100%;
    max-width: 380px
}

.sg-svg {
    width: 100%;
    height: auto;
    display: block
}

.sg-footer {
    width: 100%;
    max-width: 380px;
    display: flex;
    flex-direction: column;
    gap: 10px
}

.sg-bar-wrap {
    display: flex;
    align-items: center;
    gap: 10px
}

.sg-bar-track {
    flex: 1 1 auto;
    height: 10px;
    background: #e6edf4;
    border-radius: 999px;
    overflow: hidden
}

.sg-bar-fill {
    height: 100%;
    border-radius: 999px;
    transition: width .4s ease, background .4s ease
}

.sg-bar-num {
    font-size: 13px;
    font-weight: 800;
    min-width: 50px;
    text-align: right
}

.sg-status {
    font-size: 12px;
    font-weight: 700;
    letter-spacing: .06em;
    text-align: center;
    text-transform: uppercase
}

.sg-device-info {
    width: 100%;
    max-width: 380px;
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: 8px
}

.sg-device-name {
    font-size: 13px;
    font-weight: 800;
    color: #22384f;
    letter-spacing: .04em;
    text-transform: uppercase;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis
}

.sg-device-val {
    font-size: 28px;
    font-weight: 900;
    line-height: 1;
    transition: color .4s ease
}

.lt-wrap {
    display: flex;
    flex-direction: column;
    gap: 10px;
    padding: 4px;
    grid-column: 1/-1;
    width: 100%
}

.lt-brt-card {
    background: #e8f4fd;
    border: 1px solid #bbdefb;
    border-radius: 10px;
    padding: 10px 16px;
    display: flex;
    align-items: center;
    gap: 12px
}

.lt-brt-label {
    font-size: 11px;
    font-weight: 700;
    color: #1565c0;
    text-transform: uppercase;
    letter-spacing: .08em
}

.lt-brt-value {
    font-size: 28px;
    font-weight: 900;
    color: #1565c0;
    line-height: 1
}

.lt-channels {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 8px
}

.lt-ch {
    border: 1px solid #ebf1f7;
    border-radius: 10px;
    background: #f8f9fa;
    padding: 8px;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 3px
}

.lt-ch.lt-on {
    background: #fffde7;
    border-color: #ffe082;
    box-shadow: 0 0 10px rgba(255, 214, 0, 0.3), inset 0 3px 0 #ffd600
}

.lt-ch-name {
    font-size: 9px;
    font-weight: 700;
    color: #7c92a8;
    text-transform: uppercase;
    letter-spacing: .06em
}

.lt-bulb-svg {
    width: 40px;
    height: 54px;
    display: block
}

.lt-ch-state {
    font-size: 11px;
    font-weight: 800;
    color: #b0bec5
}

.lt-ch.lt-on .lt-ch-state {
    color: #f9a825
}

descriptor.controllerScript:
self.onInit = function() {
    var ctx = self.ctx,
        root = ctx && ctx.$container && ctx.$container[
            0];
    if (!root) return;

    function toNum(v, d) {
        var n = Number(v);
        return Number.isFinite(n) ? n : d;
    }

    function esc(v) {
        return String(v == null ? '' : v).replace(/&/g,
                '&amp;').replace(/</g, '&lt;').replace(
                />/g, '&gt;').replace(/\"/g, '&quot;')
            .replace(/'/g, '&#39;');
    }

    function boolish(v) {
        if (v === true || v === 1) return true;
        var s = String(v == null ? '' : v).toLowerCase()
            .trim();
        return s === '1' || s === 'true' || s ===
            'yes' || s === 'on';
    }

    function iso(v) {
        if (v === undefined || v === null || v === '')
            return null;
        var n = Number(v);
        if (Number.isFinite(n)) return n;
        var d = new Date(v);
        return isNaN(d.getTime()) ? null : d.getTime();
    }

    function getEntityRef(s, idx) {
        var id = null,
            name = null,
            type = null;
        if (s && s.entityId) id = (typeof s.entityId ===
                'object' && s.entityId.id) ? s.entityId
            .id : s.entityId;
        if (!id && s && s.datasource && s.datasource
            .entity && s.datasource.entity.id) id = (
                typeof s.datasource.entity.id ===
                'object' && s.datasource.entity.id.id) ?
            s.datasource.entity.id.id : s.datasource
            .entity.id;
        if (!id && s && s.entity && s.entity.id) id = (
                typeof s.entity.id === 'object' && s
                .entity.id.id) ? s.entity.id.id : s
            .entity.id;
        if (s) name = s.entityName || (s.datasource && (
            s.datasource.entityName || s
            .datasource.name)) || (s.entity && s
            .entity.name) || null;
        if (s && s.datasource && s.datasource
            .entityType) type = s.datasource.entityType;
        if (!id && name) id = name;
        if (!id) id = 'entity_' + idx;
        if (!name) name = String(id);
        return {
            id: String(id),
            name: String(name),
            entityType: type || 'DEVICE'
        };
    }

    function normalizeKey(k) {
        return String(k || '').trim().toLowerCase();
    }

    function lastPoint(data) {
        if (!Array.isArray(data) || !data.length)
        return null;
        var p = data[data.length - 1];
        if (Array.isArray(p)) return {
            ts: p[0],
            value: p[1]
        };
        if (p && typeof p === 'object') return {
            ts: p.ts,
            value: p.value !== undefined ? p.value :
                p.v
        };
        return null;
    }

    function seriesPoints(data) {
        var arr = Array.isArray(data) ? data : [];
        var out = [];
        for (var i = 0; i < arr.length; i++) {
            var p = arr[i];
            if (Array.isArray(p) && p.length > 1) {
                var ts = toNum(p[0], NaN),
                    v = toNum(p[1], NaN);
                if (Number.isFinite(ts) && Number
                    .isFinite(v)) out.push({
                    ts: ts,
                    value: v
                });
            } else if (p && typeof p === 'object') {
                var ts2 = toNum(p.ts, NaN),
                    v2 = toNum(p.value !== undefined ? p
                        .value : p.v, NaN);
                if (Number.isFinite(ts2) && Number
                    .isFinite(v2)) out.push({
                    ts: ts2,
                    value: v2
                });
            }
        }
        out.sort(function(a, b) {
            return a.ts - b.ts;
        });
        return out;
    }

    function getStore() {
        var w = window;
        if (!w.__HVAC_V2_STATE__) {
            w.__HVAC_V2_STATE__ = {
                building: null,
                device: null
            };
        }
        return w.__HVAC_V2_STATE__;
    }

    function emit(type, payload) {
        try {
            window.dispatchEvent(new CustomEvent(
                'HVAC_V2_SYNC', {
                    detail: {
                        type: type,
                        payload: payload ||
                            null,
                        ts: Date.now()
                    }
                }));
        } catch (e) {}
    }

    function subscribe(cb) {
        var fn = function(e) {
            cb((e && e.detail) || {});
        };
        window.addEventListener('HVAC_V2_SYNC', fn);
        return fn;
    }

    function clearSub(fn) {
        try {
            if (fn) window.removeEventListener(
                'HVAC_V2_SYNC', fn);
        } catch (e) {}
    }

    function issueLevel(active, lastTs, staleHrs) {
        var staleMs = Number(staleHrs || 6) * 3600000;
        var now = Date.now();
        var activeOk = boolish(active);
        if (!activeOk) return 'critical';
        if (lastTs && now - lastTs > staleMs)
        return 'warning';
        return 'healthy';
    }

    function levelRank(l) {
        return l === 'critical' ? 0 : (l === 'warning' ?
            1 : 2);
    }

    function updateState(ctx, targetState, target) {
        try {
            if (ctx && ctx.stateController && typeof ctx
                .stateController.updateState ===
                'function') {
                var params = {};
                if (target && target.id) {
                    params.entityId = {
                        entityType: (target
                            .entityType ||
                            'ASSET'),
                        id: String(target.id)
                    };
                }
                ctx.stateController.updateState(
                    targetState, params, false);
            }
        } catch (e) {}
    }

    function collectRows(ctx) {
        var rows = (ctx && ctx.data) || [];
        var map = {};
        var list = [];
        for (var i = 0; i < rows.length; i++) {
            var s = rows[i];
            if (!s || !s.dataKey) continue;
            var ref = getEntityRef(s, i);
            var item = map[ref.id];
            if (!item) {
                item = {
                    id: ref.id,
                    name: ref.name,
                    entityType: ref.entityType,
                    vals: {},
                    series: {}
                };
                map[ref.id] = item;
                list.push(item);
            }
            var nameKey = normalizeKey(s.dataKey.name);
            var labelKey = normalizeKey(s.dataKey.label);
            var key = (nameKey === 'value' && labelKey) ?
                labelKey : (nameKey || labelKey);
            var pt = lastPoint(s.data);
            if (pt) {
                item.vals[key] = pt.value;
                if (labelKey && labelKey !== key) item.vals[
                    labelKey] = pt.value;
                if (nameKey && nameKey !== key && !(nameKey ===
                        'value' && labelKey)) item.vals[
                    nameKey] = pt.value;
            }
            item.series[key] = seriesPoints(s.data);
            if (labelKey && labelKey !== key) item.series[
                labelKey] = item.series[key];
            if (nameKey && nameKey !== key && !(nameKey ===
                    'value' && labelKey)) item.series[
                nameKey] = item.series[key];
        }
        return list;
    }
    var grid = root.querySelector('#dg-grid');
    var store = getStore();
    var settings = ctx && ctx.settings ? ctx.settings :
    {};

    function toPct(v, d) {
        var n = Number(v);
        return Number.isFinite(n) ? Math.max(0, Math
            .min(100, n)) : d;
    }
    var defaultGreen = toPct(settings.greenBandPct, 55),
        defaultWarn = toPct(settings.warnBandPct, 80);
    if (defaultWarn < defaultGreen) defaultWarn =
        defaultGreen + 10;

    function first(vals, keys) {
        for (var i = 0; i < keys.length; i++) {
            var k = String(keys[i] || '').toLowerCase();
            if (vals[k] !== undefined && vals[k] !==
                null && vals[k] !== '') return vals[k];
        }
        return undefined;
    }

    function hasAny(vals, keys) {
        return first(vals, keys) !== undefined;
    }

    function numLike(v) {
        var n = Number(v);
        return Number.isFinite(n) ? n : null;
    }

    function isBinary(v) {
        var n = numLike(v);
        return n === 0 || n === 1;
    }

    function isStatusKey(k) {
        var s = normalizeKey(k);
        return s === 'value' || /(^|[^a-z0-9])(status|state|run|running|enable|enabled|alarm|fault|trip|start|stop|active|override|occupied|flow)([^a-z0-9]|$)/.test(
            s);
    }

    function detectProfile(vals) {
        if (hasAny(vals, ['coolant_temperature', 'engine_battery_voltage', 'engine_speed', 'fuel_level', 'generator_frequency', 'generator_l1_current', 'generator_l1n_voltage', 'generator_l2_current', 'generator_l2n_voltage', 'generator_l3_current'])) return 'generator_temp';
        if (hasAny(vals, ['avg', 'avgrmt', 'chwltemp', 'ratset', 'sprinkler', 'staticsp', 'staticspw'])) return 'ahu2';
        if (hasAny(vals, ['chw supply temp',
                'chw return temp',
                'buffer tank temp',
                'sec.chw supply  pressure',
                'sec.chw return pressure',
                'output power',
                'sec.chw pump 1 run hours',
                'delta temp',
                'chilled water outlet temp'
            ])) return 'chiller';
        if (hasAny(vals, ['north 1 temp',
                'north 2 temp', 'south 1 temp',
                'south 2 temp', '2nd override'
            ])) return 'prde';
        if (hasAny(vals, ['current a', 'current b',
                'current c'
            ])) return 'ebo';
        if (hasAny(vals, ['supply air temp',
                'return air', 'air flow status'
            ])) return 'ahu';
        if (hasAny(vals, ['ahu runtime', 'ra temp']))
            return 'rtpu1';
        if (hasAny(vals, ['carbon dioxide',
                'room temp 1', 'room temp 2',
                'ave temp'
            ])) return 'rtpu2';
        if (hasAny(vals, ['cmf-f116 airflow text',
                'faf-a1 airflow text'
            ])) return 'ventfan1';
        if (hasAny(vals, ['tef-g011/g012 airflow text',
                'cef-g01 airflow text'
            ])) return 'ventfan2';
        if (hasAny(vals, [
                'chilled water return temperature 1',
                'chilled water supply temperature'
            ])) return 'chillerroof1';
        if (hasAny(vals, ['ll fournos water meter',
                'ul ocean basket water meter'
            ])) return 'watermeter';
        // Support both lowercase and capitalized channel keys
        var channelKeys = [];
        for (var i = 1; i <= 12; i++) {
            channelKeys.push('channel' + i);
            channelKeys.push('Channel' + i);
        }
        if (hasAny(vals, channelKeys)) return 'lights';
        if (hasAny(vals, ['value'])) {
            var vn = numLike(vals['value']);
            if (vn !== null && !isBinary(vn)) return 'sensor';
        }
        return 'generic';
    }

    function profileLabel(p) {
        if (p === 'chiller') return 'Chiller profile';
        if (p === 'prde') return 'PRDE profile';
        if (p === 'ebo') return 'EBO profile';
        if (p === 'ahu') return 'AHU profile';
        if (p === 'generator_temp') return 'Generator temporary profile';
        if (p === 'ahu2') return 'AHU2 profile';
        if (p === 'rtpu1') return 'RTPU 1 profile';
        if (p === 'rtpu2') return 'RTPU 2 profile';
        if (p === 'ventfan1')
        return 'Vent Fan 1 profile';
        if (p === 'ventfan2')
        return 'Vent Fan 2 profile';
        if (p === 'chillerroof1')
        return 'Chiller Roof 1 profile';
