        if (p === 'lights') return 'Light Controller';
        return 'Generic telemetry';
    }

    function norm(value, min, max) {
        var n = numLike(value);
        if (n === null) return 0;
        var span = (max - min) || 1;
        return Math.max(0, Math.min(100, ((n - min) /
            span) * 100));
    }

    function gaugeTone(n) {
        if (n >= defaultWarn) return 'bad';
        if (n >= defaultGreen) return 'warn';
        return 'good';
    }

