      svg+='<rect class="tr-bar" x="'+x+'" y="'+y+'" width="'+Math.round(barW)+'" height="'+h+'"><title>'+esc(bars[b].label)+': '+bars[b].count+'</title></rect>';
      svg+='<text class="tr-val" x="'+cx+'" y="'+Math.max(10,y-4)+'" text-anchor="middle">'+bars[b].count+'</text>';
